type SQLClient={query:(text:string,values?:unknown[])=>Promise<unknown>};

/** Only UUIDs generated by the importer can select a physical edition table. */
export function editionTable(stage:string){
  if(!/^import-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(stage))
    throw new Error("Invalid IDFM storage generation");
  return `idfm_data.edition_${stage.slice(7).replaceAll("-","")}`;
}
export async function createEdition(client:SQLClient,stage:string){
  const table=editionTable(stage);
  await client.query("BEGIN");
  try{
    await client.query("CREATE SCHEMA IF NOT EXISTS idfm_data");
    // A managed, empty parent supplies the stable reader relation. Unmanaged
    // children stay outside public/schema push; no existing provider is moved.
    // Keep bulk loading invisible even to readers of the parent. Attaching an
    // unindexed child would make last-good requests scan the in-progress edition.
    await client.query(`CREATE TABLE ${table}
      (LIKE public.transit_idfm_stop_times INCLUDING DEFAULTS INCLUDING CONSTRAINTS,
       CHECK(mode='${stage}' AND agency='idfm'))`);
    await client.query(`INSERT INTO transit_feed_snapshots(id,agency,mode,data) VALUES($1,'idfm','live',$2)`,
      [`idfm:generation:${stage}`,JSON.stringify({kind:"gtfs-generation",stage,storage:"idfm-edition"})]);
    await client.query("COMMIT");
  }catch(error){await client.query("ROLLBACK");throw error;}
  return table;
}
export async function sealEdition(client:SQLClient,stage:string,signal:AbortSignal,deadline:number){
  const table=editionTable(stage),name=table.split(".")[1];
  try{
    await client.query("SET maintenance_work_mem='64MB'");
    for(const [suffix,columns,unique] of [["pk","id",true],["stop","stop_id,departure_seconds",false],["trip","trip_id,sequence",false]] as const){
      signal.throwIfAborted();
      const remaining=Math.min(360000,deadline-Date.now());
      if(remaining<=0)throw new Error("IDFM import deadline");
      await client.query(`SET statement_timeout=${remaining}`);
      // Build on an invisible complete edition, never remove an active index.
      // Constant mode is enforced by CHECK, so it needn't bloat every index key.
      await client.query(`CREATE ${unique?"UNIQUE":""} INDEX ${name}_${suffix} ON ${table}(${columns})`);
    }
    signal.throwIfAborted();
    await client.query(`ANALYZE ${table}`);
  }finally{await client.query("RESET maintenance_work_mem; SET statement_timeout='120s'");}
}
